INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Agiolax', '아지올락스', '아지올락스', '2등급', '', '임부 신중투여');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Alacepril', '알라세프릴', '알라세틸', '2등급', '', '임신 중기 및 말기에 ACE 저해제 투여시 양수과소증, 태아 및 신생아 사망, 신생아 저혈압, 신부전, 고칼륨혈증, 두개골형성부진, 사지의 구축, 두개안면변형 보고.
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Albendazole', '알벤다졸', '젠텔', '2등급', '', '동물 생식 연구 결과 태아 손상을 유발할 수 있음. 랫트와 토끼에서 기관 형성 기간 동안 투여 시(전체 신체 표면적에 대하여 정량화된 사람 권장 용량의 약 0.1–0.6 배를 경구 투여) 배아 독성 및 골격 변이가 보고. 임신가능성이 있는 여성은 이 약의 투여기간 동안 및 마지막 투여 이후 3일 까지 효과적인 피임 방법을 사용.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Albiglutide', '알비글루타이드', '-', '2등급', '', '임부에서 사용에 대한 적절한 자료가 존재하지 않으며, 예방적인 차원에서 임부에서는 이 약의 사용을 피하는 것이 나음');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Alclometasone', '알클로메타손', '알클로텍', '2등급', '', '랫트 암컷을 이용한 수태능 및 일반생식독성 시험의 고용량(450mg/kg/day)에서 분만지연 및 출생자의 사망율 증가와 성장지연이 나타났음. 주산, 수유기 시험의 10mg/kg/day이상 투여군에서 출생자의 출생 후 체중감소가 나타남. 동물 생식연구에서는 판토프라졸 5mg/kg이상의 용량에서 약한 태자독성의 증상이 관찰됨.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Alectinib', '알렉티닙', '알레센자', '2등급', '', '임부에 대한 안전성 미확립.  동물시험에서 인체 투여용량의 약 2.7배 용량 투여 시 배태자독성 및 모체 태자 흡수를 유발');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Alemtuzumab', '알렘투주맙', '렘트라다', '2등급', '', '임부에 대한 안전성 미확립.');
