INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Alfentanil', '알펜타닐', '래펜탄', '2등급', '', '임부에 대한 안전성 미확립. 신생아 호흡억제 및 금단 증상 유발 가능.');
