INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Clofazimine', '클로파지민', '람프린', '2등급', '', '임부에 대한 안전성 미확립. 사람 태반을 통과하여 태아에게 피부착색 가능성. 동물실험에서 랫트의 착상수 감소, 태자 체중감소 및 사망률 증가와 마우스의 태자 사망률 증가 및 두개골 골화 지연 나타남');
