INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Levobupivacaine', '레보부피바카인', '키사카인', '2등급', '', '이 약을 포함한 국소 마취제는 경막외 차단을 위해 사용될 때 신속히 태반을 통과하여 모체, 태아 및 신생아에게 다양한 정도의 독성을 유발할 수 있음. 분만시 진통 억제를 위해 이 약을 국소마취제로 사용한 결과 모체의 저혈압, 태아의 서맥 및 태아 감속이 나타남. 임신말기에는 마취 시 똑바로 누운 자세에서 저혈압을 더 쉽게 일으킬 수 있고 마취범위가 확대될 수 있음.');
