INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Live attenuated Measles Vaccine + Live Mumps Vaccine + Live Attenuated Rubella Vaccine', '약독화 홍역 백신 + 약독화 유행성이하선염 백신 + 약독화 풍진 백신', 'MMR 백신', '1등급', '', '임신 첫 석달 내 유행성이하선염 감염은 자연 유산율을 증가시킬 수 있음. 임신 기간 중 자연적으로 홍역에 감염되면 태아 위험도 증대. 자연유산, 사산, 선천기형 및 미숙아 비율 증가. ');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Live Attenuated Varicella-Zoster Vaccines', '약독화 수두-대상포진 백신', '바리락스', '1등급', '', '-');
