INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Mifamurtide', '미파뮤타이드', '뮤파뮤트', '2등급', '', '임부에 대한 안전성 미확립.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Migalastat', '미갈라스타트', '갈라폴드', '2등급', '', '토끼 배태자 독성 연구에서 배아-태아의 사망, 태아의 평균 체중 감소, 지골연화, 미미한 뼈 기형의 발생률 증가');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Miglitol', '미글리톨', '글리세트', '2등급', '', '안전성 미확립. 동물시험에서 300mg/Kg 이상에서 모체 독성에 의한 이차적 유해작용이 발생하는 것으로 밝혀짐.');
