INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Nipradilol', '니프라딜롤', '나이올', '2등급', '', '동물실험에서 고용량 투여시 태자의 사망률 증가 및 발육억제, 사산자수 증가, 신생자의 생존률 저하 보고.');
