INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Pirfenidone', '피르페니돈', '에스브리엣', '2등급', '', '임부에 대한 안전성 미확립. 동물실험에서 고용량(≥1000mg/kg/day)이 노출된 랫트에서 임신기간 연장과 출생률 저하, 토끼에서 유산 또는 조산이 나타남. 동물시험에서 피르페니돈 및 그 대사체는 태반을 통과하는 것으로 나타남.');
