INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Pitavastatin', '피타바스타틴', '리바로', '1등급', '', '태아 발육에 필수적인 콜레스테롤의 생합성 감소 가능성.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Plerixafor', '플레릭사포르', '모조빌', '2등급', '', '동물실험에서 기형유발(태자 사망, 사산, 착상후 소실, 태자 체중저하, 무안구증, 단지증, 심실중격결손증, 대동맥궁륜, 구상심장, 수두증, 후두실 비대, 골격계발달지연을 포함한 배태자독성) 보고.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Polaprezinc', '폴라프레징크', '폴라프레징크 캡슐', '2등급', '', '임부에 대한 안전성 미확립. ');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Polmacoxib', '폴마콕시브', '아셀렉스', '2등급', '', '비임상시험에서 최기형성은 나타나지 않았으나 랫트의 모체 독성 용량에서 배아독성이 관찰되었으며, 임부에게 이 약을 투여한 사례는 제한적임');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Pomalidomide', '포말리도마이드', '포말리스트', '1등급', '', '기형 유발이 예상됨. 구조적으로 탈리도마이드와 관련성이 있음. 탈리도마이드는 인간에게 중증의 치명적인 선천적 기형을 초래하는 기형 유발 물질로 알려져 있음. 쥐와 토끼 모두에서 발생독성 확인');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Ponatinib', '포나티닙', '이클루시그', '2등급', '', '기관형성기에 임신한 랫드 대상 배태자 발달에 대한 영향 연구 결과 배태자 독성 관찰됨. 모체 독성 용량 3mg/kg/일(사람 권장용량에서 AUC와 동등)에서 태아 흡수 증가, 체중 감소, 외형 변화, 여러 연조직 및 골격 변화, 골화 감소, 1mg/kg/일(사람 권장 용량에서 AUC의 약 24%)에서도 여러 태아 연조직 및 골화 감소를 포함한 골격 변화 등 배태자 독성 관찰 나타남');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Porfimer sodium', '포르피머 나트륨', '포토프린', '2등급', '', '동물 연구에 따르면 배태아 독성을 유발할 수 있음. 임신한 랫트와 토끼에서 태자 흡수 증가, 태자수 감소 및 태자 체중 감소가 관찰됨(사람 권장용량의 약 0.64배 정맥투여). 태자 기형은 유발되지 않음. 남성 환자 및 임신가능성이 있는 여성 환자는 치료기간 동안 및 마지막 투여 이후 5개월 까지 효과적인 피임 방법을 사용하는 것이 권고됨.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Posaconazole', '포사코나졸', '노록사필', '2등급', '', '동물실험에서 생식독성 관찰됨');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Potassium chloride', '칼륨 클로라이드', '클로켄', '2등급', '단일제에 한함', '임부에 대한 안전성 미확립');
