INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Primaquine', '프리마퀸', '프리마퀸정', '1등급', '', '임신 중 이 약의 안전한 사용법이 확립되어 있지 않음. 임부가 글루코오스-6-포스파타아제 결핍증(G-6-PD) 정상인 경우에도 태아는 정상이 아닐 수 있음. 동물 실험 데이터에서 생식 독성이 나타남. 이 약으로 치료한 동물과 세균을 대상으로 한 비임상 데이터에서, 이 약을 임신한 동물에게 투여했을 때 유전자 변이와 염색체/DNA 손상, 기형 발생, 배아 손상 및 태아 손상의 증거가 나타남. 환자는 치료 중 임신을 피해야 하며, 치료 중 그리고 치료 종료 후에도 효과적인 피임법 사용에 대해 권고됨.');
