INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Teriflunomide', '테리플루노마이드', '오바지오', '1등급', '', '임신한 여성을 대상으로 이 약을 사용한 자료는 제한적임. 동물시험에서는 생식기계 독성을 보임. 이 약을 임신한 여성에게 투여할 때에는 심각한 최기형성을 야기할 수 있음. 임신의 가능성이 있는 여성은 치료기간 그리고 치료 후 이 약의 혈장 농도가 0.02 mg/L 이상인 한 효과적인 피임을 해야함.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Teriparatide', '테리파라타이드', '포스테오', '2등급', '', '(주사제) 토끼를 이용한 정맥 내 투여에 의한 기관 형성기 투여 시험에서 태아독성(태아 사망)이 인정됨.
(프리필드펜) 토끼 연구에서 생식 독성이 나타남. 사람에 대한 잠재적인 위험성은 알려지지 않음. 가임 여성은 이 약을 사용하는 동안 효과적인 피임법을 사용해야 하며, 임신이 되는 경우 이 약의 투여를 중단해야 함.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Terlipressin', '테를리프레신', '글리프레신', '2등급', '', '자궁평활근 수축으로 임신 4개월 전 낙태 유발 가능성.
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tertomotide', '테르토모타이드', '-', '2등급', '', '임부에 대한 안전성 미확립');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Testosterone', '테스토스테론', '안드리올', '1등급', '겔제 포함', '여성 태아의 남성화 초래 가능성.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tetracycline', '테트라사이클린', '테라마이신', '2등급', '', '태자에 일과성 골발육부전, 영구적 치아착색, 법랑질형성부전 보고.
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tetrakis (2-Methoxyisobutylisonitrile) Copper(I) Tetrafluoroborate', '테트라키스 (2-메톡시이소부틸이소니트릴) 구리(I) 테트라플루오로보레이트', '-', '2등급', '', '740MBq의 휴식 시 정맥주사에 의한 자궁 내 예측 방사능량은 5.8mGy임. 0.5mGy(평균 1년 동안 기초방사선에 노출된 양과 동등한 양) 이상의 방사능량은 태아에게 심각한 위험을 야기할 수 있음.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tetrasodium 3,3-diphosphono-propane-1,2-dicarboxylate', '테트라소듐 3,3-디포스포노-프로판-1,2-디카복실레이트', '-', '2등급', '', '700MBq 투여 시, 4.27mGy 자궁에 흡수. 0.5mGy 이상의 방사선량은 태아에 위험을 끼칠 수 있는 양으로 간주됨. ');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tetrofosmin', '테트로포스민', '-', '2등급', '', '운동부하 시의 250MBq 투여 및 휴식 시의 750MBq 투여로 인한 자궁흡수선량은 8.1mGy임. 0.5mGy 이상의 방사선량은 태아에게 위험을 주는 것으로 알려짐. ');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Thalidomide', '탈리도마이드', '탈리도마이드정', '1등급', '', '단 1캡슐의 1회 용량 복용으로도 심각한 선천성 기형(사지결손(사지의 결여), 단지증(짧은 사지), 뼈의 저형성증, 외이의 이상(무이증, 귓바퀴가 작은 것, 외이도가 작거나 없는 것 포함), 안면마비, 눈의 이상(무안구증, 소안구증) 및 선천성 심장결함 등) 또는 유산 보고.
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Thallium (201Tl) Chloride', '탈륨 (201Tl) 클로라이드', '-', '2등급', '', '-');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Theophylline', '테오필린', '유니필', '2등급', '', '동물실험에서 기형발생이 보고됨. 사람 태반을 통과하여 신생아에서 구토, 신경과민 유발 가능성.');
