INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tigecycline', '타이게사이클린', '타이그실', '2등급', '', '테트라사이클린계 항생제와 같이 이 약은 임신 2-3분기 동안 투여할 때 영구적인 젖니 변색 및 가역적인 뼈 성장 억제를 유발할 수 있음. 기관 형성 기간 동안 임신한 랫트 및 토끼에게 사람에서 권장된 임상용량의 각각 5배 및 1배에 해당하는 노출 시 태자의 체중 감소 및 부골격이상(골화의 지연) 발생률 증가와 연관있음.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Timolol', '티몰롤', '티몰롤 점안액', '2등급', '점안제 포함', '임부에 대한 안전성 미확립. 장기투여 시 신생아에서 베타차단제의 징후 및 증상 관찰');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tioconazole', '티오코나졸', '티코나졸', '2등급', '크림제 포함', '랫트의 출산과 태자발달에 부정적 영향 보고');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tiotropium', '티오트로퓸', '스피리바', '2등급', '', '임부에 이 약을 투여한 임상자료는 제한적이므로, 예방적 조치로서 임신 중 이 약의 사용을 피하는 것이 권장됨.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tipiracil + Trifluridine', '티피라실 + 트리플루리딘', '론서프', '2등급', '', '동물실험(랫트)에서 Trifluridine 용량이 50mg/kg 이상(임상용량의 약 0.33배)에서 태자 체중감소, 150mg/kg(임상용량의 약 0.92배)에서 배아 치사 및 구조적 이상(꼬인 꼬리, 구개 파열, 지결손증, 전신부종, 대혈관 전위 및 골격 기형) 관찰');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tisagenlecleucel', '티사젠렉류셀', '킴리아', '2등급', '', '임부에 대한 안전성 미확립');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tizanidine', '티자니딘', '리조트릴', '2등급', '', '동물 실험에서 기형 및 독성 보고');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tobramycin', '토브라마이신', '토비', '2등급', '', '신생아에 제8뇌신경장애 가능성.');
