INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tolterodine', '톨테로딘', '디트루시톨', '2등급', '', '임부 치료에 대한 임상경험은 없음. 임신한 마우스에서의 시험은 고용량이 태자 체중 감소, 배자치사(embryolethality) 및 태자의 기형 발생률 증가를 일으킨 것으로 나타남.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Tolvaptan', '톨바프탄', '삼사카', '2등급', '', '동물실험에서 구개열, 소지증, 소안구증, 골격기형, 태아 체중감소, 태아 골화지연, 배·태자 사망 보고.');
