INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Urea (14C)', '요소 (14C)', '-', '2등급', '', '마우스 림포마 세포를 이용한 DNA- strand 절단시험에서 양성의 결과를 나타냄. 차이니스 햄스터 세포를 이용한 in vitro 염색체 이상 시험과 마우스를 이용한 in vitro 염색체 이상시험 모두에서 양성의 결과를 나타냄. ');
