INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Vaccinia Virus', '백시니아 바이러스', '-', '1등급', '', '임부에 대한 안전성 및 유효성 미확립. 태아에서 전신성 백시니아증, 사산아의 조산 및 태아사망을 초래할 수 있음.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Valaciclovir', '발라시클로비르', '발트렉스', '2등급', '', '임부에 대한 안전성 미확립. 동물실험에서 활성대사물인 Acyclovir를 과용량(200mg/kg/day) 피하투여 시 랫트의 태자기형 보고');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Valbenazine', '발베나진', '잉그레자', '2등급', '', '동물실험에서 사산 및 출산 후 출생자 사망 증가, 태자 발달 지연(체중 감소 및 골화 지연) 관찰됨');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Valganciclovir', '발간시클로비르', '발사이트', '2등급', '', '임부에 대한 안전성 미확립.
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Valproic acid', '발프로익산', '데파코트', '2등급', '', '신경관 결함(척수수막류, 척추갈림증 등), 안면 형태 이상, 구개열, 심혈관계, 신장, 비뇨생식기계 이상, 사지 기형(요골의 양측 요골무형성을 포함한 다양한 이상) 보고.
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Valsartan', '발사르탄', '디오반', '2등급', '', '임신 2~3기에 ACE저해제 투여시 태아 및 신생아의 저혈압, 고칼륨혈증, 신생아 두개골 발육부전, 무뇨증, 신부전, 양수과소증(태아사지구축, 두개안면기형, 폐발육부전과 관련 있음) 및 사망과 관련됨.');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Vancomycin', '반코마이신', '반코마이신 주사', '2등급', '', '임부에 대한 안전성 미확립');
INSERT INTO `tableName` (`성분명`, `성분명(한글 발음)`, `대표 상품명`, `임부금기(등급)`, `비고`, `허가사항`) VALUES ('Vandetanib', '반데타닙', '캡렐사', '2등급', '', '임산부에게 투여했을 때 태아에게 해를 입힐 수 있음. 인체 권장 용량인 300mg/day 투여 시에 랫트에서 배자 독성, 태아 독성과 최기형성을 나타냄. 교미 전과 수태 첫 1주 동안 투여했을 때, 착상 전 소실이 증가하였고 착상 후 소실로 인해 생존 배자의 수가 유의하게 감소함. 
